
import { useState, useEffect } from 'react'
import { supabase } from '@/lib/supabase'
import { X, Plus, Filter, Search, LogIn, LogOut, Lock, Download, Upload } from 'lucide-react'

export default function Home() {
  const [lieux, setLieux] = useState([])
  const [categories, setCategories] = useState([])
  const [villes, setVilles] = useState([])
  const [showForm, setShowForm] = useState(false)
  const [editingId, setEditingId] = useState(null)
  const [formData, setFormData] = useState({ nom: '', types: [], ville: '' })
  const [typeInput, setTypeInput] = useState('')
  const [villeInput, setVilleInput] = useState('')
  const [showTypeSuggestions, setShowTypeSuggestions] = useState(false)
  const [showVilleSuggestions, setShowVilleSuggestions] = useState(false)
  const [filtresActifs, setFiltresActifs] = useState({ types: [], villes: [] })
  const [showFilters, setShowFilters] = useState(false)
  const [searchTerm, setSearchTerm] = useState('')
  const [isAdmin, setIsAdmin] = useState(false)
  const [showLogin, setShowLogin] = useState(false)
  const [loginData, setLoginData] = useState({ email: '', password: '' })
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    checkUser()
    loadData()
    
    // Écouter les changements en temps réel
    const lieuxSubscription = supabase
      .channel('lieux_changes')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'lieux' }, loadLieux)
      .subscribe()

    return () => {
      lieuxSubscription.unsubscribe()
    }
  }, [])

  const checkUser = async () => {
    const { data: { session } } = await supabase.auth.getSession()
    setIsAdmin(!!session)
    setLoading(false)
  }

  const loadData = async () => {
    await Promise.all([loadLieux(), loadCategories(), loadVilles()])
  }

  const loadLieux = async () => {
    const { data, error } = await supabase
      .from('lieux')
      .select('*')
      .order('nom', { ascending: true })
    
    if (!error && data) setLieux(data)
  }

  const loadCategories = async () => {
    const { data, error } = await supabase
      .from('categories')
      .select('nom')
      .order('nom', { ascending: true })
    
    if (!error && data) setCategories(data.map(c => c.nom))
  }

  const loadVilles = async () => {
    const { data, error } = await supabase
      .from('villes')
      .select('nom')
      .order('nom', { ascending: true })
    
    if (!error && data) setVilles(data.map(v => v.nom))
  }

  const handleLogin = async () => {
    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        email: loginData.email,
        password: loginData.password,
      })

      if (error) throw error

      setIsAdmin(true)
      setShowLogin(false)
      setLoginData({ email: '', password: '' })
      alert('Connexion réussie !')
    } catch (error) {
      alert('Erreur de connexion : ' + error.message)
    }
  }

  const handleLogout = async () => {
    await supabase.auth.signOut()
    setIsAdmin(false)
    setShowForm(false)
    alert('Déconnexion réussie')
  }

  const ajouterLieu = async () => {
    if (!isAdmin) {
      alert('Vous devez être connecté en tant qu\'admin')
      return
    }

    if (!formData.nom || formData.types.length === 0 || !formData.ville) {
      alert('Veuillez remplir tous les champs')
      return
    }

    try {
      if (editingId) {
        const { error } = await supabase
          .from('lieux')
          .update({ nom: formData.nom, types: formData.types, ville: formData.ville })
          .eq('id', editingId)
        
        if (error) throw error
      } else {
        const { error } = await supabase
          .from('lieux')
          .insert([{ nom: formData.nom, types: formData.types, ville: formData.ville }])
        
        if (error) throw error
      }

      resetForm()
      loadLieux()
    } catch (error) {
      alert('Erreur : ' + error.message)
    }
  }

  const supprimerLieu = async (id) => {
    if (!isAdmin) return
    
    if (confirm('Supprimer ce lieu ?')) {
      const { error } = await supabase.from('lieux').delete().eq('id', id)
      if (!error) loadLieux()
    }
  }

  const editerLieu = (lieu) => {
    if (!isAdmin) return
    
    setFormData({ nom: lieu.nom, types: lieu.types, ville: lieu.ville })
    setEditingId(lieu.id)
    setShowForm(true)
  }

  const resetForm = () => {
    setFormData({ nom: '', types: [], ville: '' })
    setEditingId(null)
    setShowForm(false)
    setTypeInput('')
    setVilleInput('')
  }

  const ajouterType = async (type) => {
    if (!isAdmin) return
    
    if (type && !formData.types.includes(type)) {
      setFormData({ ...formData, types: [...formData.types, type] })
    }
    
    if (type && !categories.includes(type)) {
      await supabase.from('categories').insert([{ nom: type }])
      loadCategories()
    }
    
    setTypeInput('')
    setShowTypeSuggestions(false)
  }

  const retirerType = (type) => {
    if (!isAdmin) return
    setFormData({ ...formData, types: formData.types.filter(t => t !== type) })
  }

  const selectionnerVille = async (ville) => {
    if (!isAdmin) return
    
    setFormData({ ...formData, ville })
    
    if (ville && !villes.includes(ville)) {
      await supabase.from('villes').insert([{ nom: ville }])
      loadVilles()
    }
    
    setVilleInput('')
    setShowVilleSuggestions(false)
  }

  const toggleFiltre = (type, value) => {
    setFiltresActifs(prev => {
      const arr = prev[type]
      const newArr = arr.includes(value)
        ? arr.filter(v => v !== value)
        : [...arr, value]
      return { ...prev, [type]: newArr }
    })
  }

  const exporterDonnees = () => {
    const data = { lieux, categories, villes }
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `lieux-export-${new Date().toISOString().split('T')[0]}.json`
    a.click()
    URL.revokeObjectURL(url)
  }

  const importerDonnees = async (e) => {
    if (!isAdmin) {
      alert('Vous devez être connecté en tant qu\'admin')
      return
    }
    
    const file = e.target.files?.[0]
    if (!file) return
    
    const reader = new FileReader()
    reader.onload = async (event) => {
      try {
        const data = JSON.parse(event.target.result)
        if (data.lieux && confirm('Importer ces données ? Cela remplacera vos données actuelles.')) {
          // Supprimer anciennes données
          await supabase.from('lieux').delete().neq('id', 0)
          
          // Insérer nouvelles données
          await supabase.from('lieux').insert(data.lieux.map(l => ({
            nom: l.nom,
            types: l.types,
            ville: l.ville
          })))
          
          loadData()
          alert('Données importées avec succès !')
        }
      } catch (error) {
        alert('Erreur lors de l\'import : ' + error.message)
      }
    }
    reader.readAsText(file)
    e.target.value = ''
  }

  const lieuxFiltres = lieux.filter(lieu => {
    const matchSearch = lieu.nom.toLowerCase().includes(searchTerm.toLowerCase())
    const matchTypes = filtresActifs.types.length === 0 || 
      filtresActifs.types.some(t => lieu.types.includes(t))
    const matchVilles = filtresActifs.villes.length === 0 || 
      filtresActifs.villes.includes(lieu.ville)
    return matchSearch && matchTypes && matchVilles
  })

  const typesSuggestions = categories.filter(c => 
    c.toLowerCase().includes(typeInput.toLowerCase()) && 
    !formData.types.includes(c)
  )

  const villesSuggestions = villes.filter(v => 
    v.toLowerCase().includes(villeInput.toLowerCase())
  )

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-xl text-gray-600">Chargement...</div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50 p-4">
      {/* Modal de connexion */}
      {showLogin && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg p-6 max-w-md w-full">
            <div className="flex items-center gap-3 mb-6">
              <Lock className="text-blue-600" size={24} />
              <h2 className="text-2xl font-bold">Connexion Admin</h2>
            </div>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium mb-2">Email</label>
                <input
                  type="email"
                  value={loginData.email}
                  onChange={(e) => setLoginData({ ...loginData, email: e.target.value })}
                  onKeyPress={(e) => e.key === 'Enter' && handleLogin()}
                  className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  placeholder="admin@exemple.com"
                />
              </div>
              <div>
                <label className="block text-sm font-medium mb-2">Mot de passe</label>
                <input
                  type="password"
                  value={loginData.password}
                  onChange={(e) => setLoginData({ ...loginData, password: e.target.value })}
                  onKeyPress={(e) => e.key === 'Enter' && handleLogin()}
                  className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  placeholder="••••••••"
                />
              </div>
              <div className="flex gap-3">
                <button
                  onClick={handleLogin}
                  className="flex-1 bg-blue-600 text-white px-6 py-2 rounded-lg hover:bg-blue-700 font-medium"
                >
                  Se connecter
                </button>
                <button
                  onClick={() => setShowLogin(false)}
                  className="bg-gray-300 text-gray-700 px-6 py-2 rounded-lg hover:bg-gray-400"
                >
                  Annuler
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      <div className="max-w-7xl mx-auto">
        <div className="bg-white rounded-lg shadow-sm p-6 mb-6">
          <div className="flex justify-between items-center mb-6">
            <div>
              <h1 className="text-3xl font-bold text-gray-800">Gestionnaire de Lieux</h1>
              {isAdmin && (
                <p className="text-sm text-green-600 mt-1">✓ Mode administrateur</p>
              )}
            </div>
            <div className="flex gap-3">
              {!isAdmin ? (
                <button
                  onClick={() => setShowLogin(true)}
                  className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 flex items-center gap-2"
                >
                  <LogIn size={20} />
                  Connexion Admin
                </button>
              ) : (
                <>
                  <button
                    onClick={exporterDonnees}
                    className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 flex items-center gap-2"
                  >
                    <Download size={20} />
                    Exporter
                  </button>
                  <label className="bg-purple-600 text-white px-4 py-2 rounded-lg hover:bg-purple-700 flex items-center gap-2 cursor-pointer">
                    <Upload size={20} />
                    Importer
                    <input
                      type="file"
                      accept=".json"
                      onChange={importerDonnees}
                      className="hidden"
                    />
                  </label>
                  <button
                    onClick={() => setShowForm(!showForm)}
                    className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 flex items-center gap-2"
                  >
                    <Plus size={20} />
                    Ajouter
                  </button>
                  <button
                    onClick={handleLogout}
                    className="bg-red-600 text-white px-4 py-2 rounded-lg hover:bg-red-700 flex items-center gap-2"
                  >
                    <LogOut size={20} />
                    Déconnexion
                  </button>
                </>
              )}
            </div>
          </div>

          {showForm && isAdmin && (
            <div className="bg-gray-50 p-6 rounded-lg mb-6 border-2 border-blue-200">
              <h2 className="text-xl font-semibold mb-4">
                {editingId ? 'Modifier le lieu' : 'Nouveau lieu'}
              </h2>
              
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium mb-2">Nom</label>
                  <input
                    type="text"
                    value={formData.nom}
                    onChange={(e) => setFormData({ ...formData, nom: e.target.value })}
                    className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    placeholder="Nom du lieu"
                  />
                </div>

                <div className="relative">
                  <label className="block text-sm font-medium mb-2">Type de lieux</label>
                  <input
                    type="text"
                    value={typeInput}
                    onChange={(e) => {
                      setTypeInput(e.target.value)
                      setShowTypeSuggestions(true)
                    }}
                    onFocus={() => setShowTypeSuggestions(true)}
                    className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    placeholder="Rechercher ou ajouter un type..."
                  />
                  {showTypeSuggestions && typeInput && (
                    <div className="absolute z-10 w-full mt-1 bg-white border rounded-lg shadow-lg max-h-60 overflow-y-auto">
                      {typesSuggestions.map(cat => (
                        <div
                          key={cat}
                          onClick={() => ajouterType(cat)}
                          className="px-4 py-2 hover:bg-blue-50 cursor-pointer"
                        >
                          {cat}
                        </div>
                      ))}
                      {typeInput && !categories.includes(typeInput) && (
                        <div
                          onClick={() => ajouterType(typeInput)}
                          className="px-4 py-2 hover:bg-green-50 cursor-pointer text-green-700 font-medium border-t"
                        >
                          + Créer "{typeInput}"
                        </div>
                      )}
                    </div>
                  )}
                  <div className="flex flex-wrap gap-2 mt-2">
                    {formData.types.map(type => (
                      <span key={type} className="bg-blue-100 text-blue-800 px-3 py-1 rounded-full text-sm flex items-center gap-2">
                        {type}
                        <X size={14} className="cursor-pointer" onClick={() => retirerType(type)} />
                      </span>
                    ))}
                  </div>
                </div>

                <div className="relative">
                  <label className="block text-sm font-medium mb-2">Ville</label>
                  <input
                    type="text"
                    value={villeInput || formData.ville}
                    onChange={(e) => {
                      setVilleInput(e.target.value)
                      setShowVilleSuggestions(true)
                    }}
                    onFocus={() => setShowVilleSuggestions(true)}
                    className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    placeholder="Rechercher ou ajouter une ville..."
                  />
                  {showVilleSuggestions && villeInput && (
                    <div className="absolute z-10 w-full mt-1 bg-white border rounded-lg shadow-lg max-h-60 overflow-y-auto">
                      {villesSuggestions.map(ville => (
                        <div
                          key={ville}
                          onClick={() => selectionnerVille(ville)}
                          className="px-4 py-2 hover:bg-blue-50 cursor-pointer"
                        >
                          {ville}
                        </div>
                      ))}
                      {villeInput && !villes.includes(villeInput) && (
                        <div
                          onClick={() => selectionnerVille(villeInput)}
                          className="px-4 py-2 hover:bg-green-50 cursor-pointer text-green-700 font-medium border-t"
                        >
                          + Créer "{villeInput}"
                        </div>
                      )}
                    </div>
                  )}
                </div>

                <div className="flex gap-3">
                  <button
                    onClick={ajouterLieu}
                    className="bg-green-600 text-white px-6 py-2 rounded-lg hover:bg-green-700"
                  >
                    {editingId ? 'Modifier' : 'Ajouter'}
                  </button>
                  <button
                    onClick={resetForm}
                    className="bg-gray-300 text-gray-700 px-6 py-2 rounded-lg hover:bg-gray-400"
                  >
                    Annuler
                  </button>
                </div>
              </div>
            </div>
          )}

          <div className="flex gap-4 mb-4">
            <div className="flex-1 relative">
              <Search className="absolute left-3 top-3 text-gray-400" size={20} />
              <input
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                placeholder="Rechercher un lieu..."
              />
            </div>
            <button
              onClick={() => setShowFilters(!showFilters)}
              className={`px-4 py-2 rounded-lg flex items-center gap-2 ${
                showFilters ? 'bg-blue-600 text-white' : 'bg-gray-200 text-gray-700'
              }`}
            >
              <Filter size={20} />
              Filtres
              {(filtresActifs.types.length + filtresActifs.villes.length > 0) && (
                <span className="bg-white text-blue-600 rounded-full w-6 h-6 flex items-center justify-center text-sm font-bold">
                  {filtresActifs.types.length + filtresActifs.villes.length}
                </span>
              )}
            </button>
          </div>

          {showFilters && (
            <div className="bg-gray-50 p-4 rounded-lg mb-4 border">
              <div className="grid md:grid-cols-2 gap-6">
                <div>
                  <h3 className="font-medium mb-2">Types</h3>
                  <div className="flex flex-wrap gap-2">
                    {categories.map(cat => (
                      <button
                        key={cat}
                        onClick={() => toggleFiltre('types', cat)}
                        className={`px-3 py-1 rounded-full text-sm ${
                          filtresActifs.types.includes(cat)
                            ? 'bg-blue-600 text-white'
                            : 'bg-white border hover:bg-gray-100'
                        }`}
                      >
                        {cat}
                      </button>
                    ))}
                  </div>
                </div>
                <div>
                  <h3 className="font-medium mb-2">Villes</h3>
                  <div className="flex flex-wrap gap-2">
                    {villes.map(ville => (
                      <button
                        key={ville}
                        onClick={() => toggleFiltre('villes', ville)}
                        className={`px-3 py-1 rounded-full text-sm ${
                          filtresActifs.villes.includes(ville)
                            ? 'bg-blue-600 text-white'
                            : 'bg-white border hover:bg-gray-100'
                        }`}
                      >
                        {ville}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>

        <div className="bg-white rounded-lg shadow-sm overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-gray-100 border-b">
                <tr>
                  <th className="text-left px-6 py-3 font-semibold text-gray-700">Nom</th>
                  <th className="text-left px-6 py-3 font-semibold text-gray-700">Type de lieux</th>
                  <th className="text-left px-6 py-3 font-semibold text-gray-700">Ville</th>
                  {isAdmin && (
                    <th className="text-center px-6 py-3 font-semibold text-gray-700">Actions</th>
                  )}
                </tr>
              </thead>
              <tbody>
                {lieuxFiltres.length === 0 ? (
                  <tr>
                    <td colSpan={isAdmin ? "4" : "3"} className="text-center py-12 text-gray-500">
                      {lieux.length === 0 
                        ? 'Aucun lieu dans la base de données.'
                        : 'Aucun résultat ne correspond à vos filtres.'}
                    </td>
                  </tr>
                ) : (
                  lieuxFiltres.map(lieu => (
                    <tr key={lieu.id} className="border-b hover:bg-gray-50">
                      <td className="px-6 py-4 font-medium">{lieu.nom}</td>
                      <td className="px-6 py-4">
                        <div className="flex flex-wrap gap-1">
                          {lieu.types.map(type => (
                            <span key={type} className="bg-blue-100 text-blue-800 px-2 py-1 rounded text-xs">
                              {type}
                            </span>
                          ))}
                        </div>
                      </td>
                      <td className="px-6 py-4">{lieu.ville}</td>
                      {isAdmin && (
                        <td className="px-6 py-4">
                          <div className="flex justify-center gap-2">
                            <button
                              onClick={() => editerLieu(lieu)}
                              className="text-blue-600 hover:text-blue-800 font-medium"
                            >
                              Modifier
                            </button>
                            <button
                              onClick={() => supprimerLieu(lieu.id)}
                              className="text-red-600 hover:text-red-800 font-medium"
                            >
                              Supprimer
                            </button>
                          </div>
                        </td>
                      )}
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>

        <div className="mt-4 text-center text-sm text-gray-500">
          {lieuxFiltres.length} lieu{lieuxFiltres.length > 1 ? 'x' : ''} affiché{lieuxFiltres.length > 1 ? 's' : ''}
          {lieux.length !== lieuxFiltres.length && ` sur ${lieux.length} au total`}
        </div>
      </div>
    </div>
  )
}